import datetime
from decimal import Decimal
from django.core.management.base import BaseCommand
from destinations.models import District, Category, Destination, DestinationImage
from core.models import VerificationStatus


class Command(BaseCommand):
    help = "Idempotently import audited tourist destinations belonging exclusively to Palakkad district."

    def handle(self, *args, **options):
        self.stdout.write(self.style.NOTICE("Starting Palakkad destinations import..."))

        # 1. Ensure Palakkad District exists
        district, dist_created = District.objects.get_or_create(
            slug="palakkad",
            defaults={
                "name": "Palakkad",
                "headquarters": "Palakkad",
                "description": (
                    "Known as the Granary of Kerala across the sweeping Palakkad Gap, this diverse frontier spans "
                    "UNESCO biosphere rainforests of Silent Valley and Parambikulam Tiger Reserve, cool Nelliyampathy hills, "
                    "historic Tipu Sultan's Palakkad Fort and Kalpathy agraharam heritage, Varikkasseri Mana, and iconic Malampuzha reservoirs."
                ),
                "latitude": Decimal("10.786730"),
                "longitude": Decimal("76.654793"),
                "cover_image_url": 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Palakkad_Tipu_Fort.jpg/1280px-Palakkad_Tipu_Fort.jpg',
                "official_dtpc_website": "https://www.dtpcpalakkad.com/",
                "dtpc_contact": "+91 491 2538996 / info@dtpcpalakkad.com",
                "source_name": "DTPC Palakkad & Department of Tourism, Govt. of Kerala",
                "source_url": "https://palakkad.nic.in/tourism/",
                "verification_status": VerificationStatus.VERIFIED,
                "last_verified_date": datetime.date(2026, 11, 27),
                "valid_until": datetime.date(2027, 11, 27),
                "is_demo": False,
            },
        )
        self.stdout.write(f"District 'Palakkad': {'Created' if dist_created else 'Already exists'}")

        # 2. Ensure Categories exist (matching unified 8 tourism categories)
        categories_data = [
            ("Beaches and Coastal Attractions", "beaches-and-coastal", "bi-water", "Pristine sandy shores, estuaries, lighthouses, and coastal harbours."),
            ("Hill Stations and Nature", "hill-stations-and-nature", "bi-tree", "Western Ghats mountain peaks, ghat viewpoints, and green valleys."),
            ("Waterfalls", "waterfalls", "bi-moisture", "Cascading mountain water streams and forested natural waterfalls."),
            ("Wildlife and Ecotourism", "wildlife-and-ecotourism", "bi-shield-check", "National parks, tiger reserves, peafowl sanctuaries, and snake parks."),
            ("Dams, Lakes and Backwaters", "dams-lakes-and-backwaters", "bi-tsunami", "Irrigation dams, forest reservoirs, gardens, and tranquil backwaters."),
            ("Temples and Religious Attractions", "temples-and-religious", "bi-flower1", "Historic agraharam temples, kavus, and spiritual pilgrimage shrines."),
            ("Historical Places and Museums", "historical-places-and-museums", "bi-bank", "Forts, heritage nalukettu manas, Jain shrines, ASI monuments, and literary memorials."),
            ("Parks, Culture and Entertainment", "parks-culture-and-entertainment", "bi-stars", "Rock gardens, aerial ropeways, amusement water parks, and cultural centres."),
        ]

        categories_map = {}
        for cat_name, cat_slug, cat_icon, cat_desc in categories_data:
            cat_obj, _ = Category.objects.get_or_create(
                slug=cat_slug,
                defaults={"name": cat_name, "icon": cat_icon, "description": cat_desc},
            )
            categories_map[cat_slug] = cat_obj

